12	/*
13	 * CastInternal does not preserve nullability of the data type,
14	 * i.e. CastInternal(toNullable(toInt8(1)) as Int32) will be Int32(1).
15	 *
16	 * Cast preserves nullability according to setting `cast_keep_nullable`,
17	 * i.e. Cast(toNullable(toInt8(1)) as Int32) will be Nullable(Int32(1)) if `cast_keep_nullable` == 1.
18	**/
19	template<CastType cast_type, bool internal, typename CastName, typename FunctionName>
20	class CastOverloadResolverImpl : public IFunctionOverloadResolver
21	{
22	public:
23	    using MonotonicityForRange = FunctionCastBase::MonotonicityForRange;
24	    using Diagnostic = FunctionCastBase::Diagnostic;
25	
26	    static constexpr auto name = cast_type == CastType::accurate
27	        ? CastName::accurate_cast_name
28	        : (cast_type == CastType::accurateOrNull ? CastName::accurate_cast_or_null_name : CastName::cast_name);
29	
30	    String getName() const override { return name; }
31	
32	    size_t getNumberOfArguments() const override { return 2; }
33	
34	    ColumnNumbers getArgumentsThatAreAlwaysConstant() const override { return {1}; }
35	
36	    explicit CastOverloadResolverImpl(std::optional<Diagnostic> diagnostic_, bool keep_nullable_, bool cast_ipv4_ipv6_default_on_conversion_error_)
37	        : diagnostic(std::move(diagnostic_))
38	        , keep_nullable(keep_nullable_)
39	        , cast_ipv4_ipv6_default_on_conversion_error(cast_ipv4_ipv6_default_on_conversion_error_)
40	    {
41	    }
42	
43	    static FunctionOverloadResolverPtr create(ContextPtr context)
44	    {
45	        const auto & settings_ref = context->getSettingsRef();
46	
47	        if constexpr (internal)
48	            return createImpl({}, false /*keep_nullable*/, settings_ref.cast_ipv4_ipv6_default_on_conversion_error);
49	
50	        return createImpl({}, settings_ref.cast_keep_nullable, settings_ref.cast_ipv4_ipv6_default_on_conversion_error);
51	    }
52	
53	    static FunctionOverloadResolverPtr createImpl(std::optional<Diagnostic> diagnostic = {}, bool keep_nullable = false, bool cast_ipv4_ipv6_default_on_conversion_error = false)
54	    {
55	        assert(!internal || !keep_nullable);
56	        return std::make_unique<CastOverloadResolverImpl>(std::move(diagnostic), keep_nullable, cast_ipv4_ipv6_default_on_conversion_error);
57	    }
58	
59	protected:
60	
61	    FunctionBasePtr buildImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr & return_type) const override
62	    {
63	        DataTypes data_types(arguments.size());
64	
65	        for (size_t i = 0; i < arguments.size(); ++i)
66	            data_types[i] = arguments[i].type;
67	
68	        auto monotonicity = MonotonicityHelper::getMonotonicityInformation(arguments.front().type, return_type.get());
69	        return std::make_unique<FunctionCast<FunctionName>>(name, std::move(monotonicity), data_types, return_type, diagnostic, cast_type, cast_ipv4_ipv6_default_on_conversion_error);
70	    }
71	
72	    DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
73	    {
74	        const auto & column = arguments.back().column;
75	        if (!column)
76	            throw Exception("Second argument to " + getName() + " must be a constant string describing type."
77	                " Instead there is non-constant column of type " + arguments.back().type->getName(),
78	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
79	
80	        const auto * type_col = checkAndGetColumnConst<ColumnString>(column.get());
81	        if (!type_col)
82	            throw Exception("Second argument to " + getName() + " must be a constant string describing type."
83	                " Instead there is a column with the following structure: " + column->dumpStructure(),
84	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
85	
86	        DataTypePtr type = DataTypeFactory::instance().get(type_col->getValue<String>());
87	
88	        if constexpr (cast_type == CastType::accurateOrNull)
89	            return makeNullable(type);
90	
91	        if constexpr (internal)
92	            return type;
93	
94	        if (keep_nullable && arguments.front().type->isNullable() && type->canBeInsideNullable())
95	            return makeNullable(type);
96	
97	        return type;
98	    }
99	
100	    bool useDefaultImplementationForNulls() const override { return false; }
101	    bool useDefaultImplementationForNothing() const override { return false; }
102	    bool useDefaultImplementationForLowCardinalityColumns() const override { return false; }
103	
104	private:
105	    std::optional<Diagnostic> diagnostic;
106	    bool keep_nullable;
107	    bool cast_ipv4_ipv6_default_on_conversion_error;
108	};
109	
110	
111	struct CastOverloadName
112	{
113	    static constexpr auto cast_name = "CAST";
114	    static constexpr auto accurate_cast_name = "accurateCast";
115	    static constexpr auto accurate_cast_or_null_name = "accurateCastOrNull";
116	};
117	
118	struct CastInternalOverloadName
119	{
120	    static constexpr auto cast_name = "_CAST";
121	    static constexpr auto accurate_cast_name = "accurate_Cast";
122	    static constexpr auto accurate_cast_or_null_name = "accurate_CastOrNull";
123	};
124	
125	template <CastType cast_type>
126	using CastOverloadResolver = CastOverloadResolverImpl<cast_type, false, CastOverloadName, CastName>;
127	
128	template <CastType cast_type>
129	using CastInternalOverloadResolver = CastOverloadResolverImpl<cast_type, true, CastInternalOverloadName, CastInternalName>;
