64	void CachedReadBufferFromRemoteFS::appendFilesystemCacheLog(
65	    const FileSegment::Range & file_segment_range, CachedReadBufferFromRemoteFS::ReadType type)
66	{
67	    FilesystemCacheLogElement elem
68	    {
69	        .event_time = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()),
70	        .query_id = query_id,
71	        .source_file_path = remote_fs_object_path,
72	        .file_segment_range = { file_segment_range.left, file_segment_range.right },
73	        .requested_range = { first_offset, read_until_position },
74	        .file_segment_size = file_segment_range.size(),
75	        .cache_attempted = true,
76	        .read_buffer_id = current_buffer_id,
77	        .profile_counters = std::make_shared<ProfileEvents::Counters::Snapshot>(current_file_segment_counters.getPartiallyAtomicSnapshot()),
78	    };
79	
80	    current_file_segment_counters.reset();
81	
82	    switch (type)
83	    {
84	        case CachedReadBufferFromRemoteFS::ReadType::CACHED:
85	            elem.read_type = FilesystemCacheLogElement::ReadType::READ_FROM_CACHE;
86	            break;
87	        case CachedReadBufferFromRemoteFS::ReadType::REMOTE_FS_READ_BYPASS_CACHE:
88	            elem.read_type = FilesystemCacheLogElement::ReadType::READ_FROM_FS_BYPASSING_CACHE;
89	            break;
90	        case CachedReadBufferFromRemoteFS::ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE:
91	            elem.read_type = FilesystemCacheLogElement::ReadType::READ_FROM_FS_AND_DOWNLOADED_TO_CACHE;
92	            break;
93	    }
94	
95	    if (auto cache_log = Context::getGlobalContextInstance()->getFilesystemCacheLog())
96	        cache_log->add(elem);
97	}
