99	void CachedReadBufferFromRemoteFS::initialize(size_t offset, size_t size)
100	{
101	    if (settings.read_from_filesystem_cache_if_exists_otherwise_bypass_cache)
102	    {
103	        file_segments_holder.emplace(cache->get(cache_key, offset, size));
104	    }
105	    else
106	    {
107	        file_segments_holder.emplace(cache->getOrSet(cache_key, offset, size, is_persistent));
108	    }
109	
110	    /**
111	     * Segments in returned list are ordered in ascending order and represent a full contiguous
112	     * interval (no holes). Each segment in returned list has state: DOWNLOADED, DOWNLOADING or EMPTY.
113	     */
114	    if (file_segments_holder->file_segments.empty())
115	        throw Exception(ErrorCodes::LOGICAL_ERROR, "List of file segments cannot be empty");
116	
117	    LOG_TEST(log, "Having {} file segments to read", file_segments_holder->file_segments.size());
118	    current_file_segment_it = file_segments_holder->file_segments.begin();
119	
120	    initialized = true;
121	}
