123	SeekableReadBufferPtr CachedReadBufferFromRemoteFS::getCacheReadBuffer(size_t offset) const
124	{
125	    auto path = cache->getPathInLocalCache(cache_key, offset, is_persistent);
126	
127	    ReadSettings local_read_settings{settings};
128	    /// Do not allow to use asynchronous version of LocalFSReadMethod.
129	    local_read_settings.local_fs_method = LocalFSReadMethod::pread;
130	
131	    auto buf = createReadBufferFromFileBase(path, local_read_settings);
132	    auto * from_fd = dynamic_cast<ReadBufferFromFileDescriptor*>(buf.get());
133	    if (from_fd && from_fd->getFileSize() == 0)
134	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Attempt to read from an empty cache file: {}", path);
135	
136	    return buf;
137	}
