139	SeekableReadBufferPtr CachedReadBufferFromRemoteFS::getRemoteFSReadBuffer(FileSegmentPtr & file_segment, ReadType read_type_)
140	{
141	    switch (read_type_)
142	    {
143	        case ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE:
144	        {
145	            /**
146	            * Each downloader is elected to download at most buffer_size bytes and then any other can
147	            * continue. The one who continues download should reuse download buffer.
148	            *
149	            * TODO: Also implementation (s3, hdfs, web) buffer might be passed through file segments.
150	            * E.g. consider for query1 and query2 we need intersecting ranges like this:
151	            *
152	            *     [___________]         -- read_range_1 for query1
153	            *        [_______________]  -- read_range_2 for query2
154	            *     ^___________^______^
155	            *     | segment1 | segment2
156	            *
157	            * So query2 can reuse implementation buffer, which downloaded segment1.
158	            * Implementation buffer from segment1 is passed to segment2 once segment1 is loaded.
159	            */
160	
161	            auto remote_fs_segment_reader = file_segment->getRemoteFileReader();
162	
163	            if (remote_fs_segment_reader)
164	                return remote_fs_segment_reader;
165	
166	            remote_fs_segment_reader = remote_file_reader_creator();
167	            file_segment->setRemoteFileReader(remote_fs_segment_reader);
168	
169	            return remote_fs_segment_reader;
170	        }
171	        case ReadType::REMOTE_FS_READ_BYPASS_CACHE:
172	        {
173	            /// Result buffer is owned only by current buffer -- not shareable like in the case above.
174	
175	            if (remote_file_reader && remote_file_reader->getFileOffsetOfBufferEnd() == file_offset_of_buffer_end)
176	                return remote_file_reader;
177	
178	            remote_file_reader = remote_file_reader_creator();
179	            return remote_file_reader;
180	        }
181	        default:
182	            throw Exception(ErrorCodes::LOGICAL_ERROR, "Cannot use remote filesystem reader with read type: {}", toString(read_type));
183	    }
184	}
