186	SeekableReadBufferPtr CachedReadBufferFromRemoteFS::getReadBufferForFileSegment(FileSegmentPtr & file_segment)
187	{
188	    auto range = file_segment->range();
189	
190	    size_t wait_download_max_tries = settings.filesystem_cache_max_wait_sec;
191	    size_t wait_download_tries = 0;
192	
193	    auto download_state = file_segment->state();
194	
195	    if (settings.read_from_filesystem_cache_if_exists_otherwise_bypass_cache)
196	    {
197	        if (download_state == FileSegment::State::DOWNLOADED)
198	        {
199	            read_type = ReadType::CACHED;
200	            return getCacheReadBuffer(range.left);
201	        }
202	        else
203	        {
204	            read_type = ReadType::REMOTE_FS_READ_BYPASS_CACHE;
205	            return getRemoteFSReadBuffer(file_segment, read_type);
206	        }
207	    }
208	
209	    while (true)
210	    {
211	        switch (download_state)
212	        {
213	            case FileSegment::State::SKIP_CACHE:
214	            {
215	                read_type = ReadType::REMOTE_FS_READ_BYPASS_CACHE;
216	                return getRemoteFSReadBuffer(file_segment, read_type);
217	            }
218	            case FileSegment::State::DOWNLOADING:
219	            {
220	                size_t download_offset = file_segment->getDownloadOffset();
221	                bool can_start_from_cache = download_offset > file_offset_of_buffer_end;
222	
223	                /// If file segment is being downloaded but we can already read from already downloaded part, do that.
224	                if (can_start_from_cache)
225	                {
226	                    ///                      segment{k} state: DOWNLOADING
227	                    /// cache:           [______|___________
228	                    ///                         ^
229	                    ///                         download_offset (in progress)
230	                    /// requested_range:    [__________]
231	                    ///                     ^
232	                    ///                     file_offset_of_buffer_end
233	
234	                    read_type = ReadType::CACHED;
235	                    return getCacheReadBuffer(range.left);
236	                }
237	
238	                if (wait_download_tries++ < wait_download_max_tries)
239	                {
240	                    download_state = file_segment->wait();
241	                }
242	                else
243	                {
244	                    download_state = FileSegment::State::SKIP_CACHE;
245	                }
246	
247	                continue;
248	            }
249	            case FileSegment::State::DOWNLOADED:
250	            {
251	                read_type = ReadType::CACHED;
252	                return getCacheReadBuffer(range.left);
253	            }
254	            case FileSegment::State::EMPTY:
255	            case FileSegment::State::PARTIALLY_DOWNLOADED:
256	            {
257	                if (file_segment->getDownloadOffset() > file_offset_of_buffer_end)
258	                {
259	                    ///                      segment{k} state: PARTIALLY_DOWNLOADED
260	                    /// cache:           [______|___________
261	                    ///                         ^
262	                    ///                         download_offset (in progress)
263	                    /// requested_range:    [__________]
264	                    ///                     ^
265	                    ///                     file_offset_of_buffer_end
266	
267	                    read_type = ReadType::CACHED;
268	                    return getCacheReadBuffer(range.left);
269	                }
270	
271	                auto downloader_id = file_segment->getOrSetDownloader();
272	                if (downloader_id == file_segment->getCallerId())
273	                {
274	                    size_t download_offset = file_segment->getDownloadOffset();
275	                    bool can_start_from_cache = download_offset > file_offset_of_buffer_end;
276	
277	                    LOG_TEST(log, "Current download offset: {}, file offset of buffer end: {}", download_offset, file_offset_of_buffer_end);
278	
279	                    if (can_start_from_cache)
280	                    {
281	                        ///                      segment{k}
282	                        /// cache:           [______|___________
283	                        ///                         ^
284	                        ///                         download_offset
285	                        /// requested_range:    [__________]
286	                        ///                     ^
287	                        ///                     file_offset_of_buffer_end
288	
289	                        read_type = ReadType::CACHED;
290	                        file_segment->resetDownloader();
291	                        return getCacheReadBuffer(range.left);
292	                    }
293	
294	                    if (download_offset < file_offset_of_buffer_end)
295	                    {
296	                        ///                   segment{1}
297	                        /// cache:         [_____|___________
298	                        ///                      ^
299	                        ///                      download_offset
300	                        /// requested_range:          [__________]
301	                        ///                           ^
302	                        ///                           file_offset_of_buffer_end
303	
304	                        assert(file_offset_of_buffer_end > file_segment->getDownloadOffset());
305	                        bytes_to_predownload = file_offset_of_buffer_end - file_segment->getDownloadOffset();
306	                        assert(bytes_to_predownload < range.size());
307	                    }
308	
309	                    download_offset = file_segment->getDownloadOffset();
310	                    can_start_from_cache = download_offset > file_offset_of_buffer_end;
311	                    assert(!can_start_from_cache);
312	
313	                    read_type = ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE;
314	                    return getRemoteFSReadBuffer(file_segment, read_type);
315	                }
316	
317	                download_state = file_segment->state();
318	                continue;
319	            }
320	            case FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION:
321	            {
322	                size_t download_offset = file_segment->getDownloadOffset();
323	                bool can_start_from_cache = download_offset > file_offset_of_buffer_end;
324	
325	                if (can_start_from_cache)
326	                {
327	                    read_type = ReadType::CACHED;
328	                    return getCacheReadBuffer(range.left);
329	                }
330	                else
331	                {
332	                    read_type = ReadType::REMOTE_FS_READ_BYPASS_CACHE;
333	                    return getRemoteFSReadBuffer(file_segment, read_type);
334	                }
335	            }
336	        }
337	    }
338	}
339	
340	SeekableReadBufferPtr CachedReadBufferFromRemoteFS::getImplementationBuffer(FileSegmentPtr & file_segment)
341	{
342	    assert(!file_segment->isDownloader());
343	    assert(file_offset_of_buffer_end >= file_segment->range().left);
344	
345	    auto range = file_segment->range();
346	    bytes_to_predownload = 0;
347	
348	    Stopwatch watch(CLOCK_MONOTONIC);
349	
350	    auto read_buffer_for_file_segment = getReadBufferForFileSegment(file_segment);
351	
352	    watch.stop();
353	    current_file_segment_counters.increment(ProfileEvents::FileSegmentWaitReadBufferMicroseconds, watch.elapsedMicroseconds());
354	
355	    [[maybe_unused]] auto download_current_segment = read_type == ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE;
356	    assert(download_current_segment == file_segment->isDownloader());
357	
358	    assert(file_segment->range() == range);
359	    assert(file_offset_of_buffer_end >= range.left && file_offset_of_buffer_end <= range.right);
360	
361	    LOG_TEST(
362	        log,
363	        "Current file segment: {}, read type: {}, current file offset: {}",
364	        range.toString(),
365	        toString(read_type),
366	        file_offset_of_buffer_end);
367	
368	    read_buffer_for_file_segment->setReadUntilPosition(range.right + 1); /// [..., range.right]
369	
370	    switch (read_type)
371	    {
372	        case ReadType::CACHED:
373	        {
374	#ifndef NDEBUG
375	            auto * file_reader = dynamic_cast<ReadBufferFromFileDescriptor *>(read_buffer_for_file_segment.get());
376	            size_t file_size = file_reader->getFileSize();
377	
378	            if (file_size == 0 || range.left + file_size <= file_offset_of_buffer_end)
379	                throw Exception(
380	                    ErrorCodes::LOGICAL_ERROR,
381	                    "Unexpected state of cache file. Cache file size: {}, cache file offset: {}, "
382	                    "expected file size to be non-zero and file downloaded size to exceed current file read offset (expected: {} > {})",
383	                    file_size,
384	                    range.left,
385	                    range.left + file_size,
386	                    file_offset_of_buffer_end);
387	#endif
388	
389	            size_t seek_offset = file_offset_of_buffer_end - range.left;
390	
391	            if (file_offset_of_buffer_end < range.left)
392	                throw Exception(
393	                    ErrorCodes::LOGICAL_ERROR,
394	                    "Invariant failed. Expected {} > {} (current offset > file segment's start offset)",
395	                    file_offset_of_buffer_end,
396	                    range.left);
397	
398	            read_buffer_for_file_segment->seek(seek_offset, SEEK_SET);
399	
400	            break;
401	        }
402	        case ReadType::REMOTE_FS_READ_BYPASS_CACHE:
403	        {
404	            read_buffer_for_file_segment->seek(file_offset_of_buffer_end, SEEK_SET);
405	            break;
406	        }
407	        case ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE:
408	        {
409	            assert(file_segment->isDownloader());
410	
411	            if (bytes_to_predownload)
412	            {
413	                size_t download_offset = file_segment->getDownloadOffset();
414	                read_buffer_for_file_segment->seek(download_offset, SEEK_SET);
415	            }
416	            else
417	            {
418	                read_buffer_for_file_segment->seek(file_offset_of_buffer_end, SEEK_SET);
419	            }
420	
421	            auto download_offset = file_segment->getDownloadOffset();
422	            if (download_offset != static_cast<size_t>(read_buffer_for_file_segment->getPosition()))
423	            {
424	                auto impl_range = read_buffer_for_file_segment->getRemainingReadRange();
425	                throw Exception(
426	                    ErrorCodes::LOGICAL_ERROR,
427	                    "Buffer's offsets mismatch; cached buffer offset: {}, download_offset: {}, position: {}, implementation buffer offset: "
428	                    "{}, "
429	                    "implementation buffer reading until: {}, file segment info: {}",
430	                    file_offset_of_buffer_end,
431	                    download_offset,
432	                    read_buffer_for_file_segment->getPosition(),
433	                    impl_range.left,
434	                    *impl_range.right,
435	                    file_segment->getInfoForLog());
436	            }
437	
438	            break;
439	        }
440	    }
441	
442	    return read_buffer_for_file_segment;
443	}
444	
445	bool CachedReadBufferFromRemoteFS::completeFileSegmentAndGetNext()
446	{
447	    LOG_TEST(log, "Completed segment: {}", (*current_file_segment_it)->range().toString());
448	
449	    if (enable_logging)
450	        appendFilesystemCacheLog((*current_file_segment_it)->range(), read_type);
451	
452	    auto file_segment_it = current_file_segment_it++;
453	    auto & file_segment = *file_segment_it;
454	
455	    [[maybe_unused]] const auto & range = file_segment->range();
456	    assert(file_offset_of_buffer_end > range.right);
457	
458	    LOG_TEST(
459	        log,
460	        "Removing file segment: {}, downloader: {}, state: {}",
461	        file_segment->range().toString(),
462	        file_segment->getDownloader(),
463	        file_segment->state());
464	
465	    /// Do not hold pointer to file segment if it is not needed anymore
466	    /// so can become releasable and can be evicted from cache.
467	    /// If the status of filesegment state is SKIP_CACHE, it will not be deleted.
468	    /// It will be deleted from the cache when the holder is destructed.
469	    if ((*file_segment_it)->state() != FileSegment::State::SKIP_CACHE)
470	        file_segments_holder->file_segments.erase(file_segment_it);
471	
472	    if (current_file_segment_it == file_segments_holder->file_segments.end())
473	        return false;
474	
475	    implementation_buffer = getImplementationBuffer(*current_file_segment_it);
476	
477	    if (read_type == ReadType::CACHED)
478	        (*current_file_segment_it)->incrementHitsCount();
479	
480	    LOG_TEST(log, "New segment: {}", (*current_file_segment_it)->range().toString());
481	    return true;
482	}
