484	CachedReadBufferFromRemoteFS::~CachedReadBufferFromRemoteFS()
485	{
486	    if (enable_logging
487	        && file_segments_holder
488	        && current_file_segment_it != file_segments_holder->file_segments.end())
489	    {
490	        appendFilesystemCacheLog((*current_file_segment_it)->range(), read_type);
491	    }
