493	
494	void CachedReadBufferFromRemoteFS::predownload(FileSegmentPtr & file_segment)
495	{
496	    Stopwatch predownload_watch(CLOCK_MONOTONIC);
497	    SCOPE_EXIT({
498	        predownload_watch.stop();
499	        current_file_segment_counters.increment(ProfileEvents::FileSegmentPredownloadMicroseconds, predownload_watch.elapsedMicroseconds());
500	    });
501	
502	    if (bytes_to_predownload)
503	    {
504	        /// Consider this case. Some user needed segment [a, b] and downloaded it partially.
505	        /// But before he called complete(state) or his holder called complete(),
506	        /// some other user, who needed segment [a', b'], a < a' < b', started waiting on [a, b] to be
507	        /// downloaded because it intersects with the range he needs.
508	        /// But then first downloader fails and second must continue. In this case we need to
509	        /// download from offset a'' < a', but return buffer from offset a'.
510	        LOG_TEST(log, "Bytes to predownload: {}, caller_id: {}", bytes_to_predownload, FileSegment::getCallerId());
511	
512	        assert(implementation_buffer->getFileOffsetOfBufferEnd() == file_segment->getDownloadOffset());
513	        size_t current_offset = file_segment->getDownloadOffset();
514	        const auto & current_range = file_segment->range();
515	
516	        while (true)
517	        {
518	            bool has_more_data;
519	            {
520	                Stopwatch watch(CLOCK_MONOTONIC);
521	
522	                has_more_data = !implementation_buffer->eof();
523	
524	                watch.stop();
525	                auto elapsed = watch.elapsedMicroseconds();
526	                current_file_segment_counters.increment(ProfileEvents::FileSegmentReadMicroseconds, elapsed);
527	                ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromSourceMicroseconds, elapsed);
528	            }
529	
530	            if (!bytes_to_predownload || !has_more_data)
531	            {
532	                if (bytes_to_predownload)
533	                    throw Exception(
534	                        ErrorCodes::LOGICAL_ERROR,
535	                        "Failed to predownload remaining {} bytes. Current file segment: {}, current download offset: {}, expected: {}, "
536	                        "eof: {}",
537	                        bytes_to_predownload,
538	                        current_range.toString(),
539	                        file_segment->getDownloadOffset(),
540	                        file_offset_of_buffer_end,
541	                        implementation_buffer->eof());
542	
543	                auto result = implementation_buffer->hasPendingData();
544	
545	                if (result)
546	                {
547	                    nextimpl_working_buffer_offset = implementation_buffer->offset();
548	
549	                    auto download_offset = file_segment->getDownloadOffset();
550	                    if (download_offset != static_cast<size_t>(implementation_buffer->getPosition())
551	                        || download_offset != file_offset_of_buffer_end)
552	                        throw Exception(
553	                            ErrorCodes::LOGICAL_ERROR,
554	                            "Buffer's offsets mismatch after predownloading; download offset: {}, cached buffer offset: {}, implementation "
555	                            "buffer offset: {}, "
556	                            "file segment info: {}",
557	                            download_offset,
558	                            file_offset_of_buffer_end,
559	                            implementation_buffer->getPosition(),
560	                            file_segment->getInfoForLog());
561	                }
562	
563	                break;
564	            }
565	
566	            size_t current_impl_buffer_size = implementation_buffer->buffer().size();
567	            size_t current_predownload_size = std::min(current_impl_buffer_size, bytes_to_predownload);
568	
569	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromSourceBytes, current_impl_buffer_size);
570	
571	            bool continue_predownload = file_segment->reserve(current_predownload_size);
572	            if (continue_predownload)
573	            {
574	                LOG_TEST(log, "Left to predownload: {}, buffer size: {}", bytes_to_predownload, current_impl_buffer_size);
575	
576	                assert(file_segment->getDownloadOffset() == static_cast<size_t>(implementation_buffer->getPosition()));
577	
578	                bool success = writeCache(implementation_buffer->buffer().begin(), current_predownload_size, current_offset, *file_segment);
579	                if (success)
580	                {
581	                    current_offset += current_predownload_size;
582	
583	                    bytes_to_predownload -= current_predownload_size;
584	                    implementation_buffer->position() += current_predownload_size;
585	                }
586	                else
587	                {
588	                    read_type = ReadType::REMOTE_FS_READ_BYPASS_CACHE;
589	                    file_segment->complete(FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION);
590	
591	                    continue_predownload = false;
592	                }
593	            }
594	
595	            if (!continue_predownload)
596	            {
597	                /// We were predownloading:
598	                ///                   segment{1}
599	                /// cache:         [_____|___________
600	                ///                      ^
601	                ///                      download_offset
602	                /// requested_range:          [__________]
603	                ///                           ^
604	                ///                           file_offset_of_buffer_end
605	                /// But space reservation failed.
606	                /// So get working and internal buffer from predownload buffer, get new download buffer,
607	                /// return buffer back, seek to actual position.
608	                /// We could reuse predownload buffer and just seek to needed position, but for now
609	                /// seek is only allowed once for ReadBufferForS3 - before call to nextImpl.
610	                /// TODO: allow seek more than once with seek avoiding.
611	
612	                bytes_to_predownload = 0;
613	                file_segment->complete(FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION);
614	
615	                read_type = ReadType::REMOTE_FS_READ_BYPASS_CACHE;
616	
617	                swap(*implementation_buffer);
618	                resetWorkingBuffer();
619	
620	                implementation_buffer = getRemoteFSReadBuffer(file_segment, read_type);
621	
622	                swap(*implementation_buffer);
623	
624	                implementation_buffer->setReadUntilPosition(current_range.right + 1); /// [..., range.right]
625	                implementation_buffer->seek(file_offset_of_buffer_end, SEEK_SET);
626	
627	                LOG_TEST(
628	                    log,
629	                    "Predownload failed because of space limit. Will read from remote filesystem starting from offset: {}",
630	                    file_offset_of_buffer_end);
631	
632	                break;
633	            }
634	        }
635	    }
636	}
637	
638	bool CachedReadBufferFromRemoteFS::updateImplementationBufferIfNeeded()
639	{
640	    auto & file_segment = *current_file_segment_it;
641	    auto current_read_range = file_segment->range();
642	    auto current_state = file_segment->state();
643	
644	    assert(current_read_range.left <= file_offset_of_buffer_end);
645	    assert(!file_segment->isDownloader());
646	
647	    if (file_offset_of_buffer_end > current_read_range.right)
648	    {
649	        return completeFileSegmentAndGetNext();
650	    }
651	
652	    if (read_type == ReadType::CACHED && current_state != FileSegment::State::DOWNLOADED)
653	    {
654	        /// If current read_type is ReadType::CACHED and file segment is not DOWNLOADED,
655	        /// it means the following case, e.g. we started from CacheReadBuffer and continue with RemoteFSReadBuffer.
656	        ///                      segment{k}
657	        /// cache:           [______|___________
658	        ///                         ^
659	        ///                         download_offset
660	        /// requested_range:    [__________]
661	        ///                     ^
662	        ///                     file_offset_of_buffer_end
663	
664	        auto download_offset = file_segment->getDownloadOffset();
665	        if (download_offset == file_offset_of_buffer_end)
666	        {
667	            /// TODO: makes sense to reuse local file reader if we return here with CACHED read type again?
668	            implementation_buffer = getImplementationBuffer(*current_file_segment_it);
669	
670	            return true;
671	        }
672	        else if (download_offset < file_offset_of_buffer_end)
673	            throw Exception(
674	                ErrorCodes::LOGICAL_ERROR, "Expected {} >= {} ({})", download_offset, file_offset_of_buffer_end, getInfoForLog());
675	    }
676	
677	    if (read_type == ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE)
678	    {
679	        /**
680	        * ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE means that on previous getImplementationBuffer() call
681	        * current buffer successfully called file_segment->getOrSetDownloader() and became a downloader
682	        * for this file segment. However, the downloader's term has a lifespan of 1 nextImpl() call,
683	        * e.g. downloader reads buffer_size byte and calls completeBatchAndResetDownloader() and some other
684	        * thread can become a downloader if it calls getOrSetDownloader() faster.
685	        *
686	        * So downloader is committed to download only buffer_size bytes and then is not a downloader anymore,
687	        * because there is no guarantee on a higher level, that current buffer will not disappear without
688	        * being destructed till the end of query or without finishing the read range, which he was supposed
689	        * to read by marks range given to him. Therefore, each nextImpl() call, in case of
690	        * READ_AND_PUT_IN_CACHE, starts with getOrSetDownloader().
691	        */
692	        implementation_buffer = getImplementationBuffer(*current_file_segment_it);
693	    }
694	
695	    return true;
696	}
697	
698	bool CachedReadBufferFromRemoteFS::writeCache(char * data, size_t size, size_t offset, FileSegment & file_segment)
699	{
700	    Stopwatch watch(CLOCK_MONOTONIC);
701	
702	    try
703	    {
704	        file_segment.write(data, size, offset);
705	    }
706	    catch (ErrnoException & e)
707	    {
708	        int code = e.getErrno();
709	        if (code == /* No space left on device */28 || code == /* Quota exceeded */122)
710	        {
711	            LOG_INFO(log, "Insert into cache is skipped due to insufficient disk space. ({})", e.displayText());
712	            return false;
713	        }
714	        throw;
715	    }
716	
717	    watch.stop();
718	    auto elapsed = watch.elapsedMicroseconds();
719	    current_file_segment_counters.increment(ProfileEvents::FileSegmentCacheWriteMicroseconds, elapsed);
720	    ProfileEvents::increment(ProfileEvents::CachedReadBufferCacheWriteMicroseconds, elapsed);
721	    ProfileEvents::increment(ProfileEvents::CachedReadBufferCacheWriteBytes, size);
722	
723	    return true;
724	}
725	
726	bool CachedReadBufferFromRemoteFS::nextImpl()
727	{
728	    try
729	    {
730	        return nextImplStep();
731	    }
732	    catch (Exception & e)
733	    {
734	        e.addMessage("Cache info: {}", nextimpl_step_log_info);
735	        throw;
736	    }
737	}
738	
739	bool CachedReadBufferFromRemoteFS::nextImplStep()
740	{
741	    last_caller_id = FileSegment::getCallerId();
742	
743	    assertCorrectness();
744	
745	    if (!initialized)
746	        initialize(file_offset_of_buffer_end, getTotalSizeToRead());
747	
748	    if (current_file_segment_it == file_segments_holder->file_segments.end())
749	        return false;
750	
751	    SCOPE_EXIT({
752	        try
753	        {
754	            /// Save state of current file segment before it is completed.
755	            nextimpl_step_log_info = getInfoForLog();
756	
757	            if (current_file_segment_it == file_segments_holder->file_segments.end())
758	                return;
759	
760	            auto & file_segment = *current_file_segment_it;
761	
762	            bool download_current_segment = read_type == ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE;
763	            if (download_current_segment)
764	            {
765	                bool need_complete_file_segment = file_segment->isDownloader();
766	                if (need_complete_file_segment)
767	                {
768	                    LOG_TEST(log, "Resetting downloader {} from scope exit", file_segment->getDownloader());
769	                    file_segment->completeBatchAndResetDownloader();
770	                }
771	            }
772	
773	            assert(!file_segment->isDownloader());
774	        }
775	        catch (...)
776	        {
777	            tryLogCurrentException(__PRETTY_FUNCTION__);
778	        }
779	    });
780	
781	    bytes_to_predownload = 0;
782	
783	    if (implementation_buffer)
784	    {
785	        bool can_read_further = updateImplementationBufferIfNeeded();
786	        if (!can_read_further)
787	            return false;
788	    }
789	    else
790	    {
791	        implementation_buffer = getImplementationBuffer(*current_file_segment_it);
792	
793	        if (read_type == ReadType::CACHED)
794	            (*current_file_segment_it)->incrementHitsCount();
795	    }
796	
797	    assert(!internal_buffer.empty());
798	    swap(*implementation_buffer);
799	
800	    auto & file_segment = *current_file_segment_it;
801	    auto current_read_range = file_segment->range();
802	
803	    LOG_TEST(
804	        log,
805	        "Current segment: {}, downloader: {}, current count: {}, position: {}",
806	        current_read_range.toString(),
807	        file_segment->getDownloader(),
808	        implementation_buffer->count(),
809	        implementation_buffer->getPosition());
810	
811	    assert(current_read_range.left <= file_offset_of_buffer_end);
812	    assert(current_read_range.right >= file_offset_of_buffer_end);
813	
814	    bool result = false;
815	    size_t size = 0;
816	
817	    size_t needed_to_predownload = bytes_to_predownload;
818	    if (needed_to_predownload)
819	    {
820	        predownload(file_segment);
821	
822	        result = implementation_buffer->hasPendingData();
823	        size = implementation_buffer->available();
824	    }
825	
826	    auto download_current_segment = read_type == ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE;
827	    if (download_current_segment != file_segment->isDownloader())
828	    {
829	        throw Exception(
830	            ErrorCodes::LOGICAL_ERROR,
831	            "Incorrect segment state. Having read type: {}, file segment info: {}",
832	            toString(read_type), file_segment->getInfoForLog());
833	    }
834	
835	    if (!result)
836	    {
837	#ifndef NDEBUG
838	        if (auto * cache_file_reader = dynamic_cast<ReadBufferFromFileDescriptor *>(implementation_buffer.get()))
839	        {
840	            auto cache_file_size = cache_file_reader->getFileSize();
841	            if (cache_file_size == 0)
842	                throw Exception(
843	                    ErrorCodes::LOGICAL_ERROR, "Attempt to read from an empty cache file: {} (just before actual read)", cache_file_size);
844	        }
845	#endif
846	
847	        Stopwatch watch(CLOCK_MONOTONIC);
848	
849	        result = implementation_buffer->next();
850	
851	        watch.stop();
852	        auto elapsed = watch.elapsedMicroseconds();
853	        current_file_segment_counters.increment(ProfileEvents::FileSegmentReadMicroseconds, elapsed);
854	
855	        size = implementation_buffer->buffer().size();
856	
857	        if (read_type == ReadType::CACHED)
858	        {
859	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromCacheBytes, size);
860	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromCacheMicroseconds, elapsed);
861	        }
862	        else
863	        {
864	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromSourceBytes, size);
865	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromSourceMicroseconds, elapsed);
866	        }
867	    }
868	
869	    if (result)
870	    {
871	        if (download_current_segment)
872	        {
873	            assert(file_offset_of_buffer_end + size - 1 <= file_segment->range().right);
874	
875	            bool success = file_segment->reserve(size);
876	            if (success)
877	            {
878	                assert(file_segment->getDownloadOffset() == static_cast<size_t>(implementation_buffer->getPosition()));
879	
880	                success = writeCache(implementation_buffer->position(), size, file_offset_of_buffer_end, *file_segment);
881	                if (success)
882	                {
883	                    assert(file_segment->getDownloadOffset() <= file_segment->range().right + 1);
884	                    assert(
885	                        std::next(current_file_segment_it) == file_segments_holder->file_segments.end()
886	                        || file_segment->getDownloadOffset() == implementation_buffer->getFileOffsetOfBufferEnd());
887	                }
888	                else
889	                {
890	                    assert(file_segment->state() == FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION);
891	                }
892	            }
893	            else
894	            {
895	                LOG_DEBUG(log, "No space left in cache, will continue without cache download");
896	                file_segment->complete(FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION);
897	            }
898	
899	            if (!success)
900	            {
901	                read_type = ReadType::REMOTE_FS_READ_BYPASS_CACHE;
902	                download_current_segment = false;
903	            }
904	        }
905	
906	        /// - If last file segment was read from remote fs, then we read up to segment->range().right, but
907	        /// the requested right boundary could be segment->range().left < requested_right_boundary <  segment->range().right.
908	        /// Therefore need to resize to a smaller size. And resize must be done after write into cache.
909	        /// - If last file segment was read from local fs, then we could read more than file_segemnt->range().right, so resize is also needed.
910	        if (std::next(current_file_segment_it) == file_segments_holder->file_segments.end())
911	        {
912	            size_t remaining_size_to_read = std::min(current_read_range.right, read_until_position - 1) - file_offset_of_buffer_end + 1;
913	            size = std::min(size, remaining_size_to_read);
914	            assert(implementation_buffer->buffer().size() >= nextimpl_working_buffer_offset + size);
915	            implementation_buffer->buffer().resize(nextimpl_working_buffer_offset + size);
916	        }
917	
918	        file_offset_of_buffer_end += size;
919	
920	    }
921	
922	    swap(*implementation_buffer);
923	
924	    current_file_segment_counters.increment(ProfileEvents::FileSegmentUsedBytes, available());
925	
926	    if (download_current_segment)
927	        file_segment->completeBatchAndResetDownloader();
928	
929	    assert(!file_segment->isDownloader());
930	
931	    LOG_TEST(
932	        log,
933	        "Key: {}. Returning with {} bytes, buffer position: {} (offset: {}, predownloaded: {}), "
934	        "buffer available: {}, current range: {}, current offset: {}, file segment state: {}, download offset: {}, read_type: {}, "
935	        "reading until position: {}, started with offset: {}, remaining ranges: {}",
936	        getHexUIntLowercase(cache_key),
937	        working_buffer.size(),
938	        getPosition(),
939	        offset(),
940	        needed_to_predownload,
941	        available(),
942	        current_read_range.toString(),
943	        file_offset_of_buffer_end,
944	        FileSegment::stateToString(file_segment->state()),
945	        file_segment->getDownloadOffset(),
946	        toString(read_type),
947	        read_until_position,
