232	
233	    size_t new_pos;
234	    if (whence == SEEK_SET)
235	    {
236	        assert(offset >= 0);
237	        new_pos = offset;
238	    }
239	    else if (whence == SEEK_CUR)
240	    {
241	        new_pos = file_offset_of_buffer_end - (working_buffer.end() - pos) + offset;
242	    }
243	    else
